/// A Salsa-backed type value returned by type inference.
#[derive(Clone, Copy)]
pub struct InferredType<'db> {
    db: &'db dyn TypeDb,
    data: TypeData<'db>,
}

impl<'db> InferredType<'db> {
    pub const fn new(db: &'db dyn TypeDb, data: TypeData<'db>) -> Self {
        Self { db, data }
    }

    pub fn is_number_literal(self, value: f64) -> bool {
        matches!(
            self.data,
            TypeData::Literal(literal)
                if matches!(literal.literal(self.db), Literal::Number(number) if number.to_f64() == Some(value))
        )
    }

    pub fn is_number_or_number_literal(self) -> bool {
        matches!(self.data, TypeData::Number)
            || matches!(
                self.data,
                TypeData::Literal(literal)
                    if matches!(literal.literal(self.db), Literal::Number(_))
            )
    }

    pub fn is_bigint_literal(self, value: i64) -> bool {
        let expected = format!("{value}n");
        matches!(
            self.data,
            TypeData::Literal(literal)
                if matches!(literal.literal(self.db), Literal::BigInt(number) if canonicalize_js_bigint_literal(number.text()).as_deref() == Some(expected.as_str()))
        )
    }

    pub fn is_string_or_string_literal(self) -> bool {
        matches!(self.data, TypeData::String)
            || matches!(
                self.data,
                TypeData::Literal(literal)
                    if matches!(literal.literal(self.db), Literal::String(_))
            )
    }

    pub fn is_all_string_like(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::String)
                || matches!(
                    data,
                    TypeData::Literal(literal)
                        if matches!(literal.literal(self.db), Literal::String(_))
                )
        })
        .unwrap_or(false)
    }

    pub fn is_all_number_like(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::Number)
                || matches!(
                    data,
                    TypeData::Literal(literal)
                        if matches!(literal.literal(self.db), Literal::Number(_))
                )
        })
        .unwrap_or(false)
    }

    pub fn is_all_boolean_like(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::Boolean)
                || matches!(
                    data,
                    TypeData::Literal(literal)
                        if matches!(literal.literal(self.db), Literal::Boolean(_))
                )
        })
        .unwrap_or(false)
    }

    pub fn is_all_bigint_like(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::BigInt)
                || matches!(
                    data,
                    TypeData::Literal(literal)
                        if matches!(literal.literal(self.db), Literal::BigInt(_))
                )
        })
        .unwrap_or(false)
    }

    pub fn is_all_integer_like(self) -> bool {
        self.try_all_variants_match(|data| match data {
            TypeData::BigInt => true,
            TypeData::Literal(literal) => match literal.literal(self.db) {
                Literal::BigInt(_) => true,
                Literal::Number(number) => {
                    number.to_f64().is_some_and(|number| number.fract() == 0.0)
                }
                _ => false,
            },
            _ => false,
        })
        .unwrap_or(false)
    }

    pub fn is_all_string_array_or_tuple(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::String | TypeData::Tuple(_))
                || matches!(
                    data,
                    TypeData::Literal(literal)
                        if matches!(literal.literal(self.db), Literal::String(_))
                )
                || matches!(
                    data,
                    TypeData::InstanceOf(instance)
                        if instance.ty(self.db).is_array_class(self.db)
                )
        })
        .unwrap_or(false)
    }

    pub fn is_all_array_or_tuple(self) -> bool {
        self.try_all_variants_match(|data| {
            matches!(data, TypeData::Tuple(_))
                || matches!(
                    data,
                    TypeData::InstanceOf(instance)
                        if instance.ty(self.db).is_array_class(self.db)
                )
        })
        .unwrap_or(false)
    }

    pub fn is_regexp_literal_without_global_flag(self) -> bool {
        matches!(
        self.data,
        TypeData::Literal(literal)
            if matches!(literal.literal(self.db), Literal::RegExp(regexp) if !regexp.flags.contains('g'))
        )
    }

    pub fn regexp_literal(self) -> Option<(Text, Text)> {
        let TypeData::Literal(literal) = self.data else {
            return None;
        };
        let Literal::RegExp(regexp) = literal.literal(self.db) else {
            return None;
        };
        Some((regexp.pattern.clone(), regexp.flags.clone()))
    }

    pub fn is_array(self) -> bool {
        matches!(self.data, TypeData::InstanceOf(instance) if instance.ty(self.db).is_array_class(self.db))
    }

    /// Returns `Some(true)` for arrays whose element type resolves to a
    /// `Promise` or `PromiseLike` instance, and `Some(false)` for conclusive
    /// non-matches.
    ///
    /// Returns `None` when the element type is absent, unresolved, recursive,
    /// or exceeds the promise traversal limit.
    pub fn is_array_of_promise(self) -> Option<bool> {
        let TypeData::InstanceOf(instance) = self.data else {
            return if self.data.is_indeterminate() {
                None
            } else {
                Some(false)
            };
        };

        if !instance.ty(self.db).is_array_class(self.db) {
            return Some(false);
        }
        instance
            .type_parameters(self.db)
            .first()
            .and_then(|ty| InferredType::new(self.db, *ty).is_promise_instance())
    }

    /// Returns whether this type is an array of Promises while resolving only
    /// its outer wrappers and element type.
    pub fn is_array_of_promise_with(
        self,
        mut resolve: impl FnMut(TypeData<'db>) -> TypeData<'db>,
    ) -> Option<bool> {
        let mut data = self.data;
        let mut seen = FxHashSet::default();

        for _ in 0..MAX_PROMISE_TYPE_STEPS {
            data = resolve(data).expand_structural_global(self.db);
            if !seen.insert(data) {
                return None;
            }

            data = match data {
                TypeData::InstanceOf(instance) => {
                    if !instance.ty(self.db).is_array_class(self.db) {
                        return Some(false);
                    }
                    let element = instance.type_parameters(self.db).first()?;
                    return InferredType::new(self.db, *element)
                        .is_promise_instance_with(&mut resolve);
                }
                TypeData::MergedReference(reference) => {
                    let mut targets = reference.targets(self.db);
                    let Some(first) = targets.next() else {
                        return Some(false);
                    };
                    if targets.all(|target| target == first) {
                        first
                    } else {
                        return Some(false);
                    }
                }
                TypeData::TypeofType(typeof_type) => typeof_type.ty(self.db),
                TypeData::TypeofValue(typeof_value) => typeof_value.ty(self.db),
                TypeData::Unknown
                | TypeData::Local(_)
                | TypeData::TypeofExpression(_)
                | TypeData::AnyKeyword
                | TypeData::UnknownKeyword => return None,
                _ => return Some(false),
            };
        }

        None
    }

    pub fn is_disposable(self) -> bool {
        self.has_computed_member("Symbol.dispose")
    }

    pub fn is_async_disposable(self) -> bool {
        self.has_computed_member("Symbol.asyncDispose")
    }

    /// Returns `Some(true)` when this type resolves through an instance to
    /// `Promise` or `PromiseLike`, and `Some(false)` for conclusive non-matches.
    ///
    /// Returns `None` when traversal encounters an unresolved or recursive type,
    /// or exceeds the promise traversal limit.
    pub fn is_promise_instance(self) -> Option<bool> {
        self.is_promise_instance_with(|data| data)
    }

    /// Returns whether this type resolves through an instance to `Promise` or
    /// `PromiseLike`, resolving each type only when traversal reaches it.
    ///
    /// `resolve` receives every type before it is inspected. `Some(true)` means
    /// at least one traversed branch is Promise-like. `Some(false)` means every
    /// branch was conclusively rejected. `None` means an unresolved type,
    /// recursive path, callable ambiguity, or traversal limit prevented a
    /// conclusive negative result.
    ///
    /// Traversal follows class and interface bases, generic constraints,
    /// instances, unions, intersections, merged references, type operators,
    /// and `typeof` wrappers. It does not resolve unrelated members or generic
    /// arguments.
    pub fn is_promise_instance_with(
        self,
        mut resolve: impl FnMut(TypeData<'db>) -> TypeData<'db>,
    ) -> Option<bool> {
        let mut completed = FxHashSet::default();
        let mut pending = VecDeque::from([(self.data, Vec::new(), false, false)]);
        let mut processed = 0;
        let mut indeterminate = false;

        while let Some((data, path, is_instance_target, is_promise_like_target)) =
            pending.pop_front()
        {
            let data = resolve(data);
            if path.contains(&data) {
                indeterminate = true;
                continue;
            }
            if !completed.insert((data, is_instance_target, is_promise_like_target)) {
                continue;
            }
            if processed == MAX_PROMISE_TYPE_STEPS {
                indeterminate = true;
                continue;
            }
            processed += 1;

            if is_instance_target && data.is_promise_class(self.db) {
                return Some(true);
            }
            let is_named_promise_like = is_instance_target
                && match data {
                    TypeData::Class(class) => class
                        .name(self.db)
                        .as_ref()
                        .is_some_and(|name| name.text() == "PromiseLike"),
                    TypeData::Interface(interface) => {
                        interface.name(self.db).text() == "PromiseLike"
                    }
                    _ => false,
                };
            let is_promise_like_target = is_promise_like_target || is_named_promise_like;
            if is_promise_like_target {
                let members = match data {
                    TypeData::Class(class) => Some(class.members(self.db)),
                    TypeData::Interface(interface) => Some(interface.members(self.db)),
                    TypeData::Object(object) => Some(object.members(self.db)),
                    _ => None,
                };
                if let Some(members) = members {
                    for member in members
                        .iter()
                        .filter(|member| !member.kind.is_static() && member.kind.has_name("then"))
                    {
                        let member_ty = resolve(member.ty);
                        match InferredType::new(self.db, member_ty).is_callable() {
                            Some(true) => return Some(true),
                            Some(false) => {}
                            None => indeterminate = true,
                        }
                    }
                }
            }
            if data.is_indeterminate() {
                indeterminate = true;
                continue;
            }

            let mut child_path = path;
            child_path.push(data);
            let remaining_steps = MAX_PROMISE_TYPE_STEPS - processed;
            let available_frontier = remaining_steps.saturating_sub(pending.len());
            match data {
                TypeData::Class(class) => {
                    if let Some(base) = class.extends(self.db) {
                        if available_frontier == 0 {
                            return None;
                        }
                        pending.push_back((
                            base,
                            child_path,
                            is_instance_target,
                            is_promise_like_target,
                        ));
                    }
                }
                TypeData::Generic(generic) => {
                    if let Some(constraint) = generic.constraint(self.db) {
                        if available_frontier == 0 {
                            return None;
                        }
                        pending.push_back((
                            constraint,
                            child_path,
                            is_instance_target,
                            is_promise_like_target,
                        ));
                    } else {
                        indeterminate = true;
                    }
                }
                TypeData::InstanceOf(instance) => {
                    if available_frontier == 0 {
                        return None;
                    }
                    pending.push_back((
                        instance.ty(self.db),
                        child_path,
                        true,
                        is_promise_like_target,
                    ));
                }
                TypeData::Interface(interface) => {
                    if interface.extends(self.db).len() > available_frontier {
                        return None;
                    }
                    pending.extend(interface.extends(self.db).iter().copied().map(|child| {
                        (
                            child,
                            child_path.clone(),
                            is_instance_target,
                            is_promise_like_target,
                        )
                    }));
                }
                TypeData::Intersection(intersection) => {
                    if intersection.types(self.db).len() > available_frontier {
                        return None;
                    }
                    pending.extend(intersection.types(self.db).iter().copied().map(|child| {
                        (
                            child,
                            child_path.clone(),
                            is_instance_target,
                            is_promise_like_target,
                        )
                    }));
                }
                TypeData::MergedReference(reference) => {
                    if reference.targets(self.db).count() > available_frontier {
                        return None;
                    }
                    pending.extend(reference.targets(self.db).map(|child| {
                        (
                            child,
                            child_path.clone(),
                            is_instance_target,
                            is_promise_like_target,
                        )
                    }));
                }
                TypeData::TypeOperator(operator) => {
                    if available_frontier == 0 {
                        return None;
                    }
                    pending.push_back((
                        operator.ty(self.db),
                        child_path,
                        is_instance_target,
                        is_promise_like_target,
                    ));
                }
                TypeData::TypeofType(typeof_type) => {
                    if available_frontier == 0 {
                        return None;
                    }
                    pending.push_back((
                        typeof_type.ty(self.db),
                        child_path,
                        is_instance_target,
                        is_promise_like_target,
                    ));
                }
                TypeData::TypeofValue(typeof_value) => {
                    if available_frontier == 0 {
                        return None;
                    }
                    pending.push_back((
                        typeof_value.ty(self.db),
                        child_path,
                        is_instance_target,
                        is_promise_like_target,
                    ));
                }
                TypeData::Union(union) => {
                    if union.types(self.db).len() > available_frontier {
                        return None;
                    }
                    pending.extend(union.types(self.db).iter().copied().map(|child| {
                        (
                            child,
                            child_path.clone(),
                            is_instance_target,
                            is_promise_like_target,
                        )
                    }));
                }
                TypeData::Global
                | TypeData::GlobalType(_)
                | TypeData::BigInt
                | TypeData::Boolean
                | TypeData::Null
                | TypeData::Number
                | TypeData::String
                | TypeData::Symbol
                | TypeData::Undefined
                | TypeData::Conditional
                | TypeData::Constructor(_)
                | TypeData::Function(_)
                | TypeData::Module(_)
                | TypeData::Namespace(_)
                | TypeData::Object(_)
                | TypeData::Tuple(_)
                | TypeData::Literal(_)
                | TypeData::NeverKeyword
                | TypeData::ObjectKeyword
                | TypeData::ThisKeyword
                | TypeData::VoidKeyword => {}
                TypeData::Unknown
                | TypeData::Local(_)
                | TypeData::TypeofExpression(_)
                | TypeData::AnyKeyword
                | TypeData::UnknownKeyword => {
                    indeterminate = true;
                }
            }
        }

        if indeterminate { None } else { Some(false) }
    }

