use crate::Path;
use crate::interned_types::{
    InternedClass, InternedFunction, InternedInterface, InternedIntersection, InternedNamespace,
    InternedObject, InternedUnion, Literal, TypeData, TypeDb, TypeMember, TypeMemberKind,
