    let fs = MemoryFileSystem::default();
    fs.insert("/src/defs.ts".into(), "export const letters = ['A', 'B', 'C'] as const;");
    let mut db = TestDb::new();
    db.add(&fs, "/src/defs.ts", "export const letters = ['A', 'B', 'C'] as const;");
    let module = db.add(&fs, "/src/index.ts", "import { letters } from './defs'; declare const value: (typeof letters)[number];");
    db.add(&fs, "/src/other.ts", "export const other = 1;");
    db.events.0.lock().unwrap().clear();
