                                    mode: MemberLookupMode::Value,
                                    members: Box::default(),
                                    projection: state.projection,
                                },
                                Ok(None) => return DoesNotReturnPromise,
                                Err(()) => return Indeterminate,
                            }
                        } else {
                            let Some((name, remaining)) = state.members.split_first() else {
                                return DoesNotReturnPromise;
                            };
