        ("nursery", "useAwaitThenable", "declare const value: [number][number]; await value;", 1),
        ("nursery", "noUnsafePlusOperands", "declare const value: number[][number]; value + 1n;", 1),
        ("nursery", "noUselessTypeConversion", "declare const s: [string][number]; declare const n: [number][number]; declare const b: [boolean][number]; String(s); Number(n); Boolean(b);", 3),
        ("nursery", "useArraySortCompare", "declare const value: [number[]][number]; value.sort(); value.toSorted();", 2),
    ];
    for (group, rule, source, expected) in cases {
        let (diagnostics, _) = lint(source, group, rule);
        assert_eq!(diagnostics.len(), expected, "{rule}: {diagnostics:?}");
    }
}

#[test]
fn numeric_switches_compare_runtime_values_and_fix_decimal_cases() {
    let (diagnostics, fixes) = lint("declare const value: 0x10 | 16 | 0b10001 | -0 | 1e2 | -3; switch (value) { case 0o20: break; case 0: break; }", "nursery", "useExhaustiveSwitchCases");
    assert_eq!(diagnostics.len(), 1);
    let fix = &fixes[0];
    assert!(fix.contains("case 17:"), "{fix}");
    assert!(fix.contains("case 100:"), "{fix}");
    assert!(fix.contains("case -3:"), "{fix}");
    assert!(!fix.contains("case 16:"), "{fix}");
    assert!(fix.find("case 17:").unwrap() < fix.find("case 100:").unwrap());
    let parsed = parse(fix, JsFileSource::ts(), JsParserOptions::default());
    assert!(!parsed.has_errors());
    assert!(lint(fix, "nursery", "useExhaustiveSwitchCases").0.is_empty());
    for source in [
        "declare const value: 1 | 2; switch(value) { case NaN: break; }",
        "declare const value: 1 | 2; switch(value) { case 1e999: break; }",
        "declare const value: 1 | 1e999; switch(value) {}",
        "declare const value: 1 | number; switch(value) {}",
    ] { assert!(lint(source, "nursery", "useExhaustiveSwitchCases").0.is_empty(), "{source}"); }
}

#[test]
fn double_bitwise_not_requires_signed_32_bit_literals_or_bigints() {
    for ty in ["-2147483648", "2147483647", "0", "1 | 2", "bigint", "1n | 2n"] {
        let source = format!("declare const value: {ty}; ~~value;");
        assert_eq!(lint(&source, "nursery", "noUselessTypeConversion").0.len(), 1, "{ty}");
    }
    for ty in ["-0", "2147483648", "-2147483649", "1.5", "number", "1 | -0", "1 | 2147483648"] {
        let source = format!("declare const value: {ty}; ~~value;");
        assert!(lint(&source, "nursery", "noUselessTypeConversion").0.is_empty(), "{ty}");
    }
}
